<set-variable name="straikerV3Raw" value="@{
    try { return context.Request.Body?.As(preserveContent: true) ?? ""; } catch { return ""; }
}" />




<set-variable name="straikerV3Oversize" value="@{
    var raw = (string)context.Variables["straikerV3Raw"];
    var cap = (int)context.Variables["straikerMaxBodyBytes"];
    if (raw.Length <= cap) { return false; }
    if (!(bool)context.Variables["straikerV3Parsed"]) { return false; }
    return ((JObject)context.Variables["straikerV3Body"]).ToString(Newtonsoft.Json.Formatting.None).Length > cap;
}" />





<set-variable name="straikerV3AgentMessages" value="@{
    var outArr = new JArray();
    var path = (string)context.Variables["straikerV3Path"];
    if (!(path.Contains("/threads") || path.Contains("/assistants"))) { return outArr; }
    var b = (JObject)context.Variables["straikerV3Body"];
    var candidates = new JArray();
    if (b["content"] != null && b["messages"] == null) { candidates.Add(new JObject { ["role"] = (string)(b["role"] ?? "user"), ["content"] = b["content"] }); }
    if (b["messages"] is JArray) { foreach (var m in (JArray)b["messages"]) { candidates.Add(m); } }
    var th = b["thread"] as JObject;
    if (th != null && th["messages"] is JArray) { foreach (var m in (JArray)th["messages"]) { candidates.Add(m); } }
    if (b["additional_messages"] is JArray) { foreach (var m in (JArray)b["additional_messages"]) { candidates.Add(m); } }
    foreach (var cand in candidates) {
        var role = (string)(cand["role"] ?? "user");
        var c = cand["content"];
        string txt = "";
        if (c != null && c.Type == JTokenType.String) { txt = (string)c; }
        else if (c != null && c.Type == JTokenType.Array) {
            var parts = new List();
            foreach (var part in (JArray)c) {
                var t = part["text"];
                if (t == null) { continue; }
                if (t.Type == JTokenType.String) { parts.Add((string)t); }
                else if (t.Type == JTokenType.Object && t["value"] != null) { parts.Add((string)t["value"]); }
            }
            txt = string.Join("\n", parts);
        }
        if (!string.IsNullOrEmpty(txt)) { outArr.Add(new JObject { ["role"] = role == "assistant" ? "assistant" : "user", ["content"] = txt }); }
    }
    if (b["tool_outputs"] is JArray) {
        foreach (var o in (JArray)b["tool_outputs"]) {
            var outp = o["output"];
            if (outp == null) { continue; }
            outArr.Add(new JObject { ["role"] = "tool", ["tool_call_id"] = (string)(o["tool_call_id"] ?? ""), ["content"] = outp.Type == JTokenType.String ? (string)outp : outp.ToString(Newtonsoft.Json.Formatting.None) });
        }
    }
    return outArr;
}" />









    <set-variable name="straikerV3User" value="@{
        var mode = (string)context.Variables["straikerIdentityMode"];
        if (mode == "jwt") {
            var jwt = context.Variables.GetValueOrDefault("validatedJwt", null);
            if (jwt != null) {
                foreach (var c in new[] { "email", "preferred_username", "upn", "unique_name", "app_displayname", "azp", "appid", "sub" }) {
                    if (jwt.Claims.ContainsKey(c) && jwt.Claims[c].Length > 0 && !string.IsNullOrEmpty(jwt.Claims[c][0])) { return jwt.Claims[c][0]; }
                }
            }
        }
        if (mode == "subscription") {
            if (context.User != null && !string.IsNullOrEmpty(context.User.Email)) { return context.User.Email; }
            if (context.Subscription != null) {
                if (!string.IsNullOrEmpty(context.Subscription.Name)) { return context.Subscription.Name; }
                return "apim-sub-" + context.Subscription.Id;
            }
        }
        var h = context.Request.Headers.GetValueOrDefault("x-user-name", "");
        if (!string.IsNullOrEmpty(h)) { return h; }
        var b = (JObject)context.Variables["straikerV3Body"];
        var u = b["user"];
        if (u != null && u.Type == JTokenType.String) {
            var s = ((string)u).Trim();
            if (s.Length > 0 && s != "anonymous" && s != "default_user_id" && !s.StartsWith("user_")) { return s; }
        }
        return "";
    }" />






<set-variable name="straikerV3Preamble" value="@{
    var b = (JObject)context.Variables["straikerV3Body"];
    var sys = b["system"];
    if (sys != null && sys.Type == JTokenType.String) { return (string)sys; }
    if (sys != null && sys.Type == JTokenType.Array) {
        var parts = new List();
        foreach (var blk in (JArray)sys) { var t = blk["text"]; if (t != null && t.Type == JTokenType.String) { parts.Add((string)t); } }
        return string.Join("\n", parts);
    }
    var ins = b["instructions"];
    if (ins != null && ins.Type == JTokenType.String) { return (string)ins; }
    var msgs = b["messages"] as JArray;
    if (msgs != null) {
        foreach (var m in msgs) {
            var r = (string)(m["role"] ?? "");
            if (r != "system" && r != "developer") { continue; }
            var c = m["content"];
            if (c == null) { return ""; }
            if (c.Type == JTokenType.String) { return (string)c; }
            if (c.Type == JTokenType.Array) {
                var parts = new List();
                foreach (var p in (JArray)c) { var t = p["text"]; if (t != null && t.Type == JTokenType.String) { parts.Add((string)t); } }
                return string.Join("\n", parts);
            }
            return "";
        }
    }
    return "";
}" />
<set-variable name="straikerV3AssistantText" value="@{
    var parts = new List();
    foreach (var m in (JArray)context.Variables["straikerV3AgentMessages"]) { if ((string)m["role"] != "assistant") { parts.Add((string)m["content"]); } }
    return string.Join("\n", parts);
}" />
<set-variable name="straikerV3UserTexts" value="@{
    var b = (JObject)context.Variables["straikerV3Body"];
    if ((string)context.Variables["straikerV3Shape"] == "assistant.message") {
        var t = new JArray();
        foreach (var m in (JArray)context.Variables["straikerV3AgentMessages"]) { if ((string)m["role"] != "assistant") { t.Add((string)m["content"]); } }
        return t;
    }
    var texts = new JArray();
    var msgs = b["messages"] as JArray;
    if (msgs == null && b["input"] is JArray) { msgs = (JArray)b["input"]; }
    if (msgs != null) {
        foreach (var m in msgs) {
            if ((string)(m["role"] ?? "") != "user") { continue; }
            var c = m["content"];
            if (c == null) { continue; }
            if (c.Type == JTokenType.String) { texts.Add((string)c); continue; }
            if (c.Type != JTokenType.Array) { continue; }
            var parts = new List();
            foreach (var p in (JArray)c) {
                var t = p["text"];
                if (t != null && t.Type == JTokenType.String) { parts.Add((string)t); continue; }
                var tr = p["content"];
                if ((string)(p["type"] ?? "") == "tool_result" && tr != null) {
                    if (tr.Type == JTokenType.String) { parts.Add((string)tr); }
                    else if (tr.Type == JTokenType.Array) {
                        foreach (var q in (JArray)tr) { var qt = q["text"]; if (qt != null && qt.Type == JTokenType.String) { parts.Add((string)qt); } }
                    }
                }
            }
            texts.Add(string.Join("\n", parts));
        }
        return texts;
    }
    var inp = b["input"];
    if (inp != null && inp.Type == JTokenType.String) { texts.Add((string)inp); return texts; }
    var pr = b["prompt"];
    if (pr != null && pr.Type == JTokenType.String) { texts.Add((string)pr); }
    return texts;
}" />






<set-variable name="straikerV3Agent" value="@{
    var pinned = (string)context.Variables["straikerAgentRef"];
    if (!string.IsNullOrEmpty(pinned)) { return pinned; }
    if ((bool)context.Variables["straikerAllowCallerAgent"]) {
        var h = context.Request.Headers.GetValueOrDefault("x-s6r-agent", "").Trim();
        if (!string.IsNullOrEmpty(h)) { return h; }
    }
    var ua = (string)context.Variables["straikerV3UaClient"];
    if (ua == "claude") { return (string)context.Variables["straikerClaudeAgentName"]; }
    if (ua == "codex") { return "Codex (APIM)"; }
    if (ua == "opencode") { return "OpenCode (APIM)"; }
    if (ua == "cursor") { return "Cursor (APIM)"; }
    // Automatic enumeration. Nothing above named the application, so name it from the APIM context:
    // every API (default), subscription, product, or calling Entra application becomes its own agent
    // instead of collapsing into the platform's catch-all. straikerAgentNameFrom=none keeps the catch-all.
    var from = (string)context.Variables["straikerAgentNameFrom"];
    if (from == "api" && context.Api != null && !string.IsNullOrEmpty(context.Api.Name)) { return context.Api.Name; }
    if (from == "product" && context.Product != null && !string.IsNullOrEmpty(context.Product.Name)) { return context.Product.Name; }
    if (from == "subscription" && context.Subscription != null) {
        return !string.IsNullOrEmpty(context.Subscription.Name) ? context.Subscription.Name : ("apim-sub-" + context.Subscription.Id);
    }
    if (from == "jwt-app") {
        var jwt = context.Variables.GetValueOrDefault("validatedJwt", null);
        if (jwt != null) {
            foreach (var c in new[] { "app_displayname", "azp", "appid" }) {
                if (jwt.Claims.ContainsKey(c) && jwt.Claims[c].Length > 0 && !string.IsNullOrEmpty(jwt.Claims[c][0])) { return jwt.Claims[c][0]; }
            }
        }
    }
    return "";
}" />





<set-variable name="straikerV3Session" value="@{
    var hdr = context.Request.Headers.GetValueOrDefault("x-claude-code-session-id", "");
    if (!string.IsNullOrEmpty(hdr)) { return hdr.Trim(); }
    var b = (JObject)context.Variables["straikerV3Body"];
    var uid = b["metadata"]?["user_id"];
    if (uid != null && uid.Type == JTokenType.String) {
        try { var parsed = JObject.Parse((string)uid); var sid = (string)parsed["session_id"]; if (!string.IsNullOrEmpty(sid)) { return sid; } } catch { }
    }
    var direct = b["metadata"]?["session_id"];
    if (direct != null && direct.Type == JTokenType.String && !string.IsNullOrEmpty((string)direct)) { return (string)direct; }
    var top = b["session_id"];
    if (top != null && top.Type == JTokenType.String && !string.IsNullOrEmpty((string)top)) { return (string)top; }
    var xs = context.Request.Headers.GetValueOrDefault("x-session-id", "");
    if (!string.IsNullOrEmpty(xs)) { return xs.Trim(); }
    if (((string)context.Variables["straikerV3Shape"]).StartsWith("assistant.")) {
        // .../threads/{thread_id}/... -> the agent thread is the session (create-and-run has no id yet)
        var segs = (context.Request.OriginalUrl.Path ?? "").Split('/');
        for (int i = 0; i < segs.Length - 1; i++) {
            if (string.Equals(segs[i], "threads", StringComparison.OrdinalIgnoreCase) && segs[i + 1].StartsWith("thread_", StringComparison.OrdinalIgnoreCase)) { return segs[i + 1]; }
        }
    }
    var cx = context.Request.Headers.GetValueOrDefault("session-id", "");   // Codex CLI
    if (!string.IsNullOrEmpty(cx)) { return cx.Trim(); }
    var texts = (JArray)context.Variables["straikerV3UserTexts"];
    var first = texts.Count > 0 ? (string)texts[0] : "";
    var pre = (string)context.Variables["straikerV3Preamble"];
    if (string.IsNullOrEmpty(first) && string.IsNullOrEmpty(pre)) { return ""; }
    var seed = ((string)context.Variables["straikerV3User"] ?? "") + "\0" + ((string)context.Variables["straikerV3Agent"] ?? "") + "\0" + pre + "\0" + first;
    using (var sha = System.Security.Cryptography.SHA256.Create()) {
        var h = sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(seed));
        var sb = new System.Text.StringBuilder();
        foreach (var x in h) { sb.Append(x.ToString("x2")); }
        return "apim-" + sb.ToString().Substring(0, 32);
    }
}" />


<set-variable name="straikerV3Request" value="@{
    var b = (JObject)context.Variables["straikerV3Body"];
    var keep = new HashSet {
        "model","messages","tools","tool_choice","functions","function_call","temperature","top_p","n","stream",
        "stream_options","stop","max_tokens","max_completion_tokens","presence_penalty","frequency_penalty","logit_bias",
        "response_format","seed","logprobs","top_logprobs","parallel_tool_calls","reasoning_effort","modalities","audio",
        "prediction","store","service_tier","web_search_options","prompt","suffix","echo","best_of","system","stop_sequences",
        "top_k","thinking","container","mcp_servers","context_management","output_format","input","instructions",
        "previous_response_id","truncation","text","include","reasoning","max_output_tokens","background","conversation"
    };
    var cred = new HashSet { "authorization_token", "authorization", "headers" };
    var outObj = new JObject();
    foreach (var p in b.Properties()) {
        if (!keep.Contains(p.Name)) { continue; }
        if ((p.Name == "tools" || p.Name == "mcp_servers") && p.Value is JArray) {
            var arr = new JArray();
            foreach (var entry in (JArray)p.Value) {
                var eo = entry as JObject;
                if (eo == null) { arr.Add(entry); continue; }
                var clean = new JObject();
                foreach (var q in eo.Properties()) { clean[q.Name] = cred.Contains(q.Name.ToLowerInvariant()) ? (JToken)"[redacted]" : q.Value; }
                arr.Add(clean);
            }
            outObj[p.Name] = arr;
            continue;
        }
        outObj[p.Name] = p.Value;
    }
    // One shape per agent. An agent's archetype is fixed by its first traffic and afterwards only the
    // matching shape is scored (measured: a chat_assistant scores a flat prompt but not messages; an
    // autonomous_agent scores messages but not a flat prompt). Everything non-coding through APIM is
    // therefore relayed as a messages array (autonomous_agent), the Kong/LiteLLM convention.
    var shape = (string)context.Variables["straikerV3Shape"];
    if (shape == "assistant.message") {
        outObj = new JObject { ["messages"] = (JArray)context.Variables["straikerV3AgentMessages"] };
    }
    if (shape == "openai.completion") {
        var pr = outObj["prompt"];
        string ptxt = null;
        if (pr != null && pr.Type == JTokenType.String) { ptxt = (string)pr; }
        else if (pr is JArray && ((JArray)pr).All(x => x.Type == JTokenType.String)) { ptxt = string.Join("\n", ((JArray)pr).Select(x => (string)x)); }
        if (ptxt != null) {
            outObj["messages"] = new JArray { new JObject { ["role"] = "user", ["content"] = ptxt } };
            outObj.Remove("prompt"); outObj.Remove("suffix"); outObj.Remove("echo"); outObj.Remove("best_of");
        }
    }
    var inp = outObj["input"];
    if (inp != null && inp.Type == JTokenType.String) {
        outObj["input"] = new JArray { new JObject { ["role"] = "user", ["content"] = new JArray { new JObject { ["type"] = "input_text", ["text"] = (string)inp } } } };
    }
    var sid = (string)context.Variables["straikerV3Session"];
    if (!string.IsNullOrEmpty(sid)) { outObj["session_id"] = sid; }
    var user = (string)context.Variables["straikerV3User"];
    if (!string.IsNullOrEmpty(user)) {
        // `original.processed.Meta.user` is what the gateway path reads (Kong/LiteLLM); `user_name` is the
        // documented v3 field the flat text-completion path reads (measured: a completion session had no
        // identity without it). Both carry the same principal.
        outObj["original"] = new JObject { ["processed"] = new JObject { ["Meta"] = new JObject { ["user"] = user } } };
        outObj["user_name"] = user;
    }
    // `network` is a documented v3 turn field (ip, user_agent): recorded on the turn, never scored.
    var net = new JObject();
    var ip = context.Request.IpAddress;
    if (!string.IsNullOrEmpty(ip)) { net["ip"] = ip; }
    var ua = context.Request.Headers.GetValueOrDefault("User-Agent", "");
    if (!string.IsNullOrEmpty(ua)) { net["user_agent"] = ua.Length > 200 ? ua.Substring(0, 200) : ua; }
    if (net.Count > 0) { outObj["network"] = net; }
    return outObj;
}" />












<set-variable name="straikerV3ReplayReason" value="@{
    var listJson = context.Variables.GetValueOrDefault("straikerV3BlockedList", "[]");
    JArray list;
    try { list = JArray.Parse(listJson ?? "[]"); } catch { return ""; }
    if (list.Count == 0) { return ""; }
    var digests = (JArray)context.Variables["straikerV3UserDigests"];
    foreach (var e in list) {
        var d = (string)(e["d"] ?? "");
        if (string.IsNullOrEmpty(d)) { continue; }
        foreach (var x in digests) { if ((string)x == d) { return (string)(e["r"] ?? "Blocked by Straiker policy."); } }
    }
    return "";
}" />












